#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <ctype.h>

#define MAX_MERCHANT_NAME 128
#define MAX_LOG_PATH 256
#define CIRCUIT_OPEN_THRESHOLD 5
#define CIRCUIT_RESET_TIMEOUT 30
#define MAX_TRANSACTIONS 1024

typedef enum { CIRCUIT_CLOSED, CIRCUIT_OPEN, CIRCUIT_HALF_OPEN } CircuitState;

typedef struct {
    CircuitState state;
    int failure_count;
    time_t last_failure_time;
    int success_count_half_open;
} CircuitBreaker;

typedef struct {
    char merchant_name[MAX_MERCHANT_NAME];
    double amount;
    int transaction_id;
    time_t timestamp;
} Transaction;

typedef struct {
    CircuitBreaker breaker;
    Transaction ledger[MAX_TRANSACTIONS];
    int ledger_count;
    char audit_log_dir[MAX_LOG_PATH];
} PaymentProcessor;

static int g_next_txn_id = 1000;

void init_processor(PaymentProcessor *proc, const char *log_dir) {
    memset(proc, 0, sizeof(PaymentProcessor));
    proc->breaker.state = CIRCUIT_CLOSED;
    strncpy(proc->audit_log_dir, log_dir, MAX_LOG_PATH - 1);
    proc->audit_log_dir[MAX_LOG_PATH - 1] = '\0';
}

int circuit_breaker_allow(CircuitBreaker *cb) {
    time_t now = time(NULL);
    switch (cb->state) {
        case CIRCUIT_CLOSED:
            return 1;
        case CIRCUIT_OPEN:
            if (difftime(now, cb->last_failure_time) >= CIRCUIT_RESET_TIMEOUT) {
                cb->state = CIRCUIT_HALF_OPEN;
                cb->success_count_half_open = 0;
                return 1;
            }
            return 0;
        case CIRCUIT_HALF_OPEN:
            return 1;
    }
    return 0;
}

void circuit_breaker_record_success(CircuitBreaker *cb) {
    if (cb->state == CIRCUIT_HALF_OPEN) {
        cb->success_count_half_open++;
        if (cb->success_count_half_open >= 3) {
            cb->state = CIRCUIT_CLOSED;
            cb->failure_count = 0;
        }
    } else {
        cb->failure_count = 0;
    }
}

void circuit_breaker_record_failure(CircuitBreaker *cb) {
    cb->failure_count++;
    cb->last_failure_time = time(NULL);
    if (cb->failure_count >= CIRCUIT_OPEN_THRESHOLD) {
        cb->state = CIRCUIT_OPEN;
    }
}

/* Sanitize a string for safe inclusion in SSI variable values.
 * Encodes HTML entities and strips SSI directive markers. */
static void sanitize_for_ssi(const char *input, char *output, size_t outlen) {
    size_t j = 0;
    for (size_t i = 0; input[i] && j < outlen - 1; i++) {
        switch (input[i]) {
            case '<':
                if (j + 4 < outlen) { memcpy(output + j, "&lt;", 4); j += 4; }
                break;
            case '>':
                if (j + 4 < outlen) { memcpy(output + j, "&gt;", 4); j += 4; }
                break;
            case '"':
                if (j + 6 < outlen) { memcpy(output + j, "&quot;", 6); j += 6; }
                break;
            case '&':
                if (j + 5 < outlen) { memcpy(output + j, "&amp;", 5); j += 5; }
                break;
            case '-':
                /* Prevent SSI comment sequences <!-- */
                if (i >= 3 && input[i-1] == '-' && input[i-2] == '!' && input[i-3] == '<') {
                    /* Already encoded '<' above, but double-check */
                    if (j + 1 < outlen) { output[j++] = '-'; }
                } else {
                    if (j + 1 < outlen) { output[j++] = '-'; }
                }
                break;
            default:
                if (isprint((unsigned char)input[i])) {
                    output[j++] = input[i];
                }
                break;
        }
    }
    output[j] = '\0';
}

/* Generates an audit trail entry in SSI-compatible format for the
 * web-based admin dashboard. The dashboard uses Apache with mod_include
 * to render .shtml audit pages. */
int write_audit_entry(PaymentProcessor *proc, Transaction *txn, const char *status) {
    char filepath[512];
    char timestamp_buf[64];
    char safe_merchant[MAX_MERCHANT_NAME * 6]; /* room for entity encoding */
    struct tm *tm_info;
    FILE *fp;

    tm_info = localtime(&txn->timestamp);
    if (tm_info == NULL) {
        /* Fall back to a safe fixed timestamp string on conversion failure */
        strncpy(timestamp_buf, "00000000_000000", sizeof(timestamp_buf) - 1);
        timestamp_buf[sizeof(timestamp_buf) - 1] = '\0';
    } else {
        strftime(timestamp_buf, sizeof(timestamp_buf), "%Y%m%d_%H%M%S", tm_info);
    }

    snprintf(filepath, sizeof(filepath), "%s/txn_%d_%s.shtml",
             proc->audit_log_dir, txn->transaction_id, timestamp_buf);

    fp = fopen(filepath, "w");
    if (!fp) return -1;

    /* Sanitize merchant name before embedding in SSI template */
    sanitize_for_ssi(txn->merchant_name, safe_merchant, sizeof(safe_merchant));

    /* Write the audit page header */
    fprintf(fp, "<!--#set var=\"txn_id\" value=\"%d\" -->\n", txn->transaction_id);
    fprintf(fp, "<!--#set var=\"amount\" value=\"%.2f\" -->\n", txn->amount);
    fprintf(fp, "<!--#set var=\"status\" value=\"%s\" -->\n", status);
    /* Merchant name is sanitized to prevent SSI injection */
    fprintf(fp, "<!--#set var=\"merchant\" value=\"%s\" -->\n", safe_merchant);
    fprintf(fp, "<!--#include virtual=\"/templates/audit_row.shtml\" -->\n");

    fclose(fp);
    return 0;
}

/* Validates basic transaction parameters including merchant name safety */
int validate_transaction(Transaction *txn) {
    if (txn->amount <= 0.0 || txn->amount > 999999.99) return 0;
    if (strlen(txn->merchant_name) == 0) return 0;
    if (strlen(txn->merchant_name) >= MAX_MERCHANT_NAME) return 0;
    /* Reject merchant names containing SSI-like patterns as defense in depth */
    if (strstr(txn->merchant_name, "<!--") != NULL) return 0;
    if (strstr(txn->merchant_name, "-->") != NULL) return 0;
    return 1;
}

int simulate_gateway_call(Transaction *txn) {
    /* Simulate 20% failure rate */
    return (rand() % 5 == 0) ? -1 : 0;
}

int process_payment(PaymentProcessor *proc, const char *merchant, double amount) {
    Transaction txn;
    int result;

    if (!circuit_breaker_allow(&proc->breaker)) {
        fprintf(stderr, "Circuit open: rejecting payment for merchant\n");
        return -2;
    }

    memset(&txn, 0, sizeof(Transaction));
    strncpy(txn.merchant_name, merchant, MAX_MERCHANT_NAME - 1);
    txn.merchant_name[MAX_MERCHANT_NAME - 1] = '\0';
    txn.amount = amount;
    txn.transaction_id = g_next_txn_id++;
    txn.timestamp = time(NULL);

    if (!validate_transaction(&txn)) {
        fprintf(stderr, "Invalid transaction parameters\n");
        return -1;
    }

    result = simulate_gateway_call(&txn);

    if (result == 0) {
        circuit_breaker_record_success(&proc->breaker);
        if (proc->ledger_count < MAX_TRANSACTIONS) {
            proc->ledger[proc->ledger_count++] = txn;
        }
        write_audit_entry(proc, &txn, "APPROVED");
        return txn.transaction_id;
    } else {
        circuit_breaker_record_failure(&proc->breaker);
        write_audit_entry(proc, &txn, "DECLINED");
        return -1;
    }
}

int main(int argc, char *argv[]) {
    PaymentProcessor proc;
    srand((unsigned)time(NULL));

    init_processor(&proc, "/var/www/audit");

    /* Process sample transactions */
    const char *merchants[] = {"Acme Corp", "Bob's Widgets", "CyberShop"};
    double amounts[] = {49.99, 150.00, 299.95};

    for (int i = 0; i < 3; i++) {
        int txn_id = process_payment(&proc, merchants[i], amounts[i]);
        if (txn_id > 0) {
            printf("Payment processed: TXN#%d for %s ($%.2f)\n",
                   txn_id, merchants[i], amounts[i]);
        } else if (txn_id == -2) {
            printf("Circuit breaker open, payment rejected\n");
        } else {
            printf("Payment declined for %s\n", merchants[i]);
        }
    }

    return 0;
}
